$path=Resolve-Path 'outputs/Excel Column Mapper.html'
$script:content=[IO.File]::ReadAllText($path)
function Replace-Section([string]$start,[string]$end,[string]$replacement){$a=$script:content.IndexOf($start);$b=$script:content.IndexOf($end,$a);if($a -lt 0 -or $b -lt 0){throw "Missing section: $start"};$script:content=$script:content.Substring(0,$a)+$replacement+$script:content.Substring($b)}
$validator=@'
function validateOutput(result){let sources=datasets.filter(d=>d.selected),sourceIds=new Map(),outputIds=new Map(),outputsById=new Map(),fieldStats=template.fields.map(f=>({field:f.name,expected:0,correct:0,mismatched:0,missing:0,unexpected:0})),mismatches=[],sourceStats=[];for(let d of sources)for(let row of d.rows)sourceIds.set(row.__sourceRowId,{d,row});for(let o of result.rows){let id=o.__sourceRowId;outputIds.set(id,(outputIds.get(id)||0)+1);if(!outputsById.has(id))outputsById.set(id,[]);outputsById.get(id).push(o);}let missingIds=[...sourceIds.keys()].filter(id=>!outputIds.has(id)),additionalRows=result.rows.filter(o=>!sourceIds.has(o.__sourceRowId)),duplicateOutputIds=[...outputIds.values()].reduce((n,c)=>n+Math.max(0,c-1),0),matchedRecords=0,totalRowMismatches=0;for(let d of sources){let local={file:d.file,sheet:d.sheet,sourceRecords:d.rows.length,outputRecords:0,matchedRecords:0,mismatches:0,conflicts:0,missingRequired:0,status:'PASS'};for(let row of d.rows){let id=row.__sourceRowId,outs=outputsById.get(id)||[];local.outputRecords+=outs.length;if(outs.length!==1){local.mismatches++;totalRowMismatches++;mismatches.push({file:d.file,sheet:d.sheet,row:row.__sourceRowNumber,column:'(record)',field:'(record)',expected:'Exactly one output record',actual:String(outs.length),reason:outs.length?'Duplicate output record':'Source record missing'});continue;}let o=outs[0],rowErrors=0;for(let f of template.fields){let expected=resolveTarget(d,row,f.name);local.conflicts+=expected.conflicts.length;if(!expected.mapped)continue;let stat=fieldStats.find(x=>x.field===f.name);stat.expected++;let actual=o[f.name]==null?'':o[f.name],exp=expected.value==null?'':expected.value;if(String(actual)===String(exp)){stat.correct++;}else{stat.mismatched++;rowErrors++;let isMissing=exp!==''&&actual==='',isUnexpected=exp===''&&actual!=='';if(isMissing)stat.missing++;if(isUnexpected)stat.unexpected++;mismatches.push({file:d.file,sheet:d.sheet,row:row.__sourceRowNumber,column:expected.sources.join(' + '),field:f.name,expected:String(exp),actual:String(actual),reason:isMissing?'Expected value is missing':isUnexpected?'Unexpected value in output':'Value differs from mapped source or defined transformation'});}}if(template.fields.some(f=>f.required&&resolveTarget(d,row,f.name).mapped&&String(resolveTarget(d,row,f.name).value??'')===''))local.missingRequired++;if(rowErrors===0){local.matchedRecords++;matchedRecords++;}else{local.mismatches++;totalRowMismatches++;}}let hasUnmapped=d.headers.some(h=>!d.map?.[h]),ambiguous=d.headers.some(h=>suggest(h,d).confidence==='Low'&&!d.map?.[h]);local.status=local.mismatches?'FAIL':(local.conflicts||hasUnmapped||ambiguous||local.missingRequired)?'WARNING':'PASS';sourceStats.push(local);}
let expectedValues=fieldStats.reduce((n,f)=>n+f.expected,0),correctValues=fieldStats.reduce((n,f)=>n+f.correct,0),mismatchedValues=fieldStats.reduce((n,f)=>n+f.mismatched,0),missingValues=fieldStats.reduce((n,f)=>n+f.missing,0),unexpectedValues=fieldStats.reduce((n,f)=>n+f.unexpected,0),sourceRecords=sourceIds.size,outputRecords=result.rows.length,additionalCount=additionalRows.length+duplicateOutputIds,recordErrors=missingIds.length+additionalCount,recordPct=sourceRecords?Math.max(0,(sourceRecords-Math.min(sourceRecords,recordErrors))/sourceRecords*100):100,fieldPct=expectedValues?correctValues/expectedValues*100:100;
let expectedHashes=new Map(),actualHashes=new Map(),valueHeaders=result.headers;for(let d of sources)for(let row of d.rows){let expected=valueHeaders.map(h=>{if(h==='Source File Name')return d.file;if(h==='Source Sheet Name')return d.sheet;return resolveTarget(d,row,h).value??'';});let key=JSON.stringify(expected);expectedHashes.set(key,(expectedHashes.get(key)||0)+1);}for(let o of result.rows){let key=JSON.stringify(valueHeaders.map(h=>o[h]??''));actualHashes.set(key,(actualHashes.get(key)||0)+1);}let expectedDuplicates=[...expectedHashes.values()].reduce((n,c)=>n+Math.max(0,c-1),0),actualDuplicates=[...actualHashes.values()].reduce((n,c)=>n+Math.max(0,c-1),0),duplicateRecordsIntroduced=Math.max(0,actualDuplicates-expectedDuplicates);let sourceConflicts=sourceStats.reduce((n,s)=>n+s.conflicts,0),missingRequiredRows=sourceStats.reduce((n,s)=>n+s.missingRequired,0),status=(missingIds.length||additionalCount||duplicateRecordsIntroduced||mismatchedValues||unexpectedValues)?'FAIL':(sourceConflicts||result.unmapped||missingRequiredRows||sources.some(d=>d.headers.some(h=>suggest(h,d).confidence==='Low'&&!d.map?.[h])))?'WARNING':'PASS';return {status,sourceRecords,outputRecords,selectedWorksheets:sources.length,matchedRecords,recordsWithMismatches:totalRowMismatches+additionalCount,missingRecords:missingIds.length,additionalRecords:additionalCount,duplicateRecordsIntroduced,expectedValues,correctValues,mismatchedValues,missingValues,unexpectedValues,recordPct,fieldPct,fieldStats,sourceStats,mismatches,unmappedColumns:result.unmapped,sourceConflicts,missingRequiredRows};}
'@
Replace-Section 'function validateOutput(result){' 'function renderValidationSummary(v){' $validator
